css:
body{font-family:Inter,system-ui,Arial,sans-serif;background:#f4f7fb;color:#101728;margin:0;padding:26px}
.wrap{max-width:1100px;margin:0 auto}h1{font-size:1.5rem}table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #e3e9f0;border-radius:10px;overflow:hidden;font-size:.84rem}
th,td{text-align:left;padding:9px 11px;border-bottom:1px solid #eef2f6;vertical-align:top}th{background:#0D1426;color:#fff;font-size:.7rem;text-transform:uppercase}
code{background:#eef3f8;padding:1px 5px;border-radius:4px}td.p{color:#44586a;font-size:.8rem}.note{background:#fff;border-left:4px solid #D64E41;border:1px solid #e3e9f0;border-radius:0 10px 10px 0;padding:13px 16px;margin:12px 0;font-size:.9rem}
